-- Overlay: draws patrol paths, wander areas and alternative spawn points on the world map.
--
-- Routes use anti-aliased textures (Media/, generated by tools/make_textures.py) drawn in
-- two passes: every outline first, then every core on top, so joints stay clean. Paths are
-- smoothed (Chaikin) so raw waypoints become curves, and sharp turns and ends get round caps.
-- Wander areas are a soft filled disc with the same outlined border. Everything belongs to a
-- rare group (see Coords.GroupsForMap) and is highlighted together with the group's pin.
local addonName, ns = ...

local Overlay = {}
ns.Overlay = Overlay

local MEDIA = "Interface\\AddOns\\" .. addonName .. "\\Media\\"
local KINDS = {  -- texture and draw order (higher sublevel draws on top)
    area = { file = MEDIA .. "area.tga", layer = "BORDER", sublevel = 0 },
    lineOutline = { file = MEDIA .. "line-outline.tga", layer = "ARTWORK", sublevel = 0, line = true },
    capOutline = { file = MEDIA .. "cap-outline.tga", layer = "ARTWORK", sublevel = 1 },
    lineCore = { file = MEDIA .. "line-core.tga", layer = "ARTWORK", sublevel = 2, line = true },
    capCore = { file = MEDIA .. "cap-core.tga", layer = "ARTWORK", sublevel = 3 },
}

-- thickness: on-screen pixels of the whole stroke (outline included); for spawn dots it is
-- the dot's diameter.
local CREAM, GOLD = { 1.0, 0.93, 0.72, 1.0 }, { 1.0, 0.78, 0.15, 1.0 }
local LOOKS = {
    normal = {
        path = { core = CREAM, thickness = 5 },
        wander = { core = { 1.0, 0.93, 0.72, 0.9 }, thickness = 4, area = { 1.0, 0.85, 0.5, 0.18 } },
        spot = { core = CREAM, thickness = 8 },
        zone = { core = { 1.0, 0.93, 0.72, 0.5 }, thickness = 3 },
    },
    highlight = {
        path = { core = GOLD, thickness = 7 },
        wander = { core = GOLD, thickness = 7, area = { 1.0, 0.7, 0.2, 0.32 } },
        spot = { core = GOLD, thickness = 12 },
        zone = { core = GOLD, thickness = 4 },
    },
}
-- Spawn areas: each point is padded by this many screen pixels before taking the hull,
-- sampled at ZONE_PAD_SAMPLES directions so the outline gets rounded ends.
local ZONE_PADDING = 14
local ZONE_PAD_SAMPLES = 12
local OUTLINE_ALPHA = 0.75
local DIM_ALPHA = 0.3
local SMOOTH_ITERATIONS = 2
local CAP_MIN_TURN = math.rad(25)  -- smaller turns join cleanly without a cap
-- WoW does not render lines much shorter than their thickness, so points closer than this
-- fraction of the widest stroke are dropped before drawing. Depends on zoom.
local MIN_SEGMENT_FACTOR = 0.6
local REDRAW_DELAY = 0.15  -- seconds after the last zoom step before geometry is rebuilt

local frame
local pools, active = {}, {}
local shapes = {}  -- [group] = list of parts { kind, lines = {}, caps = {}, area = texture? }
local highlighted        -- set of highlighted groups, nil when none
local highlightedTarget  -- what Highlight was given, to restore it after a redraw
local lastDraw     -- { map, uiMapID, groups } to rebuild geometry after zooming
local redrawToken = 0

for kind in pairs(KINDS) do pools[kind], active[kind] = {}, {} end

-- Pools -------------------------------------------------------------------------
local function Acquire(kind)
    local region = table.remove(pools[kind])
    if not region then
        local def = KINDS[kind]
        region = def.line and frame:CreateLine(nil, def.layer, nil, def.sublevel)
            or frame:CreateTexture(nil, def.layer, nil, def.sublevel)
        region:SetTexture(def.file, "CLAMP", "CLAMP", "LINEAR")
        region:SetSnapToPixelGrid(false)
        region:SetTexelSnappingBias(0)
    end
    region:Show()
    local list = active[kind]
    list[#list + 1] = region
    return region
end

function Overlay.Clear()
    for kind, list in pairs(active) do
        for _, region in ipairs(list) do
            region:Hide()
            region:ClearAllPoints()
            table.insert(pools[kind], region)
        end
        wipe(list)
    end
    wipe(shapes)
    highlighted, highlightedTarget = nil, nil
end

-- Geometry ------------------------------------------------------------------------
-- Chaikin corner cutting: each pass replaces every corner with two points at 1/4 and 3/4
-- of its segments, turning the polyline into a smooth curve. Open paths keep their ends.
local function Smooth(pts, closed)
    for _ = 1, SMOOTH_ITERATIONS do
        local n = #pts / 2
        if n < 3 then return pts end
        local out = {}
        if not closed then out[1], out[2] = pts[1], pts[2] end
        local last = closed and n or n - 1
        for i = 1, last do
            local j = (i % n) + 1
            local x1, y1, x2, y2 = pts[2 * i - 1], pts[2 * i], pts[2 * j - 1], pts[2 * j]
            out[#out + 1] = 0.75 * x1 + 0.25 * x2
            out[#out + 1] = 0.75 * y1 + 0.25 * y2
            out[#out + 1] = 0.25 * x1 + 0.75 * x2
            out[#out + 1] = 0.25 * y1 + 0.75 * y2
        end
        if not closed then
            -- Two statements on purpose: in a multiple assignment both "#out + 1" would be
            -- evaluated first and point at the same slot.
            out[#out + 1] = pts[2 * n - 1]
            out[#out + 1] = pts[2 * n]
        end
        pts = out
    end
    return pts
end

-- Drops points closer than minLength to the last kept point. Open paths always keep their
-- final point (replacing the last kept one if needed) so the route still reaches its end.
local function Simplify(pts, closed, minLength)
    local n = #pts / 2
    if n < 3 then return pts end
    local out = { pts[1], pts[2] }
    local minSq = minLength * minLength
    for i = 2, n do
        local x, y = pts[2 * i - 1], pts[2 * i]
        local dx, dy = x - out[#out - 1], y - out[#out]
        if dx * dx + dy * dy >= minSq then
            out[#out + 1] = x
            out[#out + 1] = y
        elseif i == n and not closed then
            if #out > 2 then
                out[#out - 1], out[#out] = x, y  -- distinct slots, safe as one assignment
            else
                out[3], out[4] = x, y
            end
        end
    end
    if closed and #out < 6 then return pts end  -- too small to simplify, keep its shape
    return out
end

-- Convex hull (Andrew's monotone chain) of a flat point list; returns a closed polygon as a
-- flat list in counter-clockwise order, without repeating the first point.
local function ConvexHull(flat)
    local points = {}
    for i = 1, #flat, 2 do points[#points + 1] = { flat[i], flat[i + 1] } end
    table.sort(points, function(a, b) return a[1] < b[1] or (a[1] == b[1] and a[2] < b[2]) end)
    if #points < 3 then
        local out = {}
        for _, p in ipairs(points) do
            out[#out + 1] = p[1]
            out[#out + 1] = p[2]
        end
        return out
    end
    local function Cross(o, a, b)
        return (a[1] - o[1]) * (b[2] - o[2]) - (a[2] - o[2]) * (b[1] - o[1])
    end
    local lower, upper = {}, {}
    for _, p in ipairs(points) do
        while #lower >= 2 and Cross(lower[#lower - 1], lower[#lower], p) <= 0 do
            table.remove(lower)
        end
        lower[#lower + 1] = p
    end
    for i = #points, 1, -1 do
        local p = points[i]
        while #upper >= 2 and Cross(upper[#upper - 1], upper[#upper], p) <= 0 do
            table.remove(upper)
        end
        upper[#upper + 1] = p
    end
    table.remove(lower)
    table.remove(upper)
    local out = {}
    for _, list in ipairs({ lower, upper }) do
        for _, p in ipairs(list) do
            out[#out + 1] = p[1]
            out[#out + 1] = p[2]
        end
    end
    return out
end

-- Rounded region around spawn points: every point becomes a small circle of samples and
-- the hull of all samples is the padded outline (works for 2+ points).
local function SpawnArea(flat, padding)
    local samples = {}
    for i = 1, #flat, 2 do
        for k = 0, ZONE_PAD_SAMPLES - 1 do
            local angle = 2 * math.pi * k / ZONE_PAD_SAMPLES
            samples[#samples + 1] = flat[i] + padding * math.cos(angle)
            samples[#samples + 1] = flat[i + 1] + padding * math.sin(angle)
        end
    end
    return ConvexHull(samples)
end

local function TurnAngle(ax, ay, bx, by, cx, cy)
    local a1 = math.atan2(by - ay, bx - ax)
    local a2 = math.atan2(cy - by, cx - bx)
    local d = math.abs(a2 - a1) % (2 * math.pi)
    return d > math.pi and 2 * math.pi - d or d
end

-- Points needing a round cap: open ends and sharp turns.
local function CapPoints(pts, closed)
    local caps = {}
    local n = #pts / 2
    for i = 1, n do
        local isEnd = not closed and (i == 1 or i == n)
        local needsCap = isEnd
        if not isEnd then
            local p = ((i - 2) % n) + 1
            local q = (i % n) + 1
            needsCap = TurnAngle(pts[2 * p - 1], pts[2 * p], pts[2 * i - 1], pts[2 * i],
                pts[2 * q - 1], pts[2 * q]) >= CAP_MIN_TURN
        end
        if needsCap then caps[#caps + 1] = { pts[2 * i - 1], pts[2 * i] } end
    end
    return caps
end

-- Exposed for the offline test suite (tests/test_lua_geometry.py).
Overlay._Smooth = Smooth
Overlay._Simplify = Simplify
Overlay._CapPoints = CapPoints
Overlay._ConvexHull = ConvexHull
Overlay._SpawnArea = SpawnArea

-- Styling -------------------------------------------------------------------------
-- Mode of a group's shapes, plus its own highlight color when one was given.
local function ModeFor(group)
    if highlighted == nil then return "normal" end
    local mark = highlighted[group]
    if not mark then return "dim" end
    return "highlight", type(mark) == "table" and mark or nil
end

local function ApplyLook(map, shape, mode, color)
    local look = (mode == "highlight" and LOOKS.highlight or LOOKS.normal)[shape.kind]
    local alpha = mode == "dim" and DIM_ALPHA or 1
    local width = look.thickness / math.max(map:GetCanvasScale(), 0.01)
    local c = color and { color[1], color[2], color[3], 1 } or look.core
    for _, line in ipairs(shape.lines) do
        line:SetThickness(width)
        if line.isCore then
            line:SetVertexColor(c[1], c[2], c[3], c[4] * alpha)
        else
            line:SetVertexColor(1, 1, 1, OUTLINE_ALPHA * alpha)
        end
    end
    for _, cap in ipairs(shape.caps) do
        cap:SetSize(width, width)
        if cap.isCore then
            cap:SetVertexColor(c[1], c[2], c[3], c[4] * alpha)
        else
            cap:SetVertexColor(1, 1, 1, OUTLINE_ALPHA * alpha)
        end
    end
    if shape.area then
        local a = look.area
        local r, g, b = a[1], a[2], a[3]
        if color then r, g, b = color[1], color[2], color[3] end
        shape.area:SetVertexColor(r, g, b, a[4] * alpha)
    end
end

local function ApplyGroupLook(map, group)
    local mode, color = ModeFor(group)
    for _, part in ipairs(shapes[group]) do ApplyLook(map, part, mode, color) end
end

-- Drawing -------------------------------------------------------------------------
-- A dot marking a point where the rare can also spawn: just a cap pair, sized by its look.
local function DrawSpot(x, y)
    local width, height = frame:GetSize()
    local shape = { kind = "spot", lines = {}, caps = {} }
    for _, kindName in ipairs({ "capOutline", "capCore" }) do
        local cap = Acquire(kindName)
        cap:SetPoint("CENTER", frame, "TOPLEFT", x * width, -y * height)
        cap.isCore = kindName == "capCore"
        shape.caps[#shape.caps + 1] = cap
    end
    return shape
end

local function DrawShape(map, points, closed, kind)
    local width, height = frame:GetSize()
    local pts = {}
    for i = 1, #points, 2 do
        pts[i], pts[i + 1] = points[i] * width, points[i + 1] * height
    end
    local shape = { kind = kind, lines = {}, caps = {} }

    if kind == "wander" then
        local minX, minY, maxX, maxY = math.huge, math.huge, -math.huge, -math.huge
        for i = 1, #pts, 2 do
            minX, maxX = math.min(minX, pts[i]), math.max(maxX, pts[i])
            minY, maxY = math.min(minY, pts[i + 1]), math.max(maxY, pts[i + 1])
        end
        shape.area = Acquire("area")
        shape.area:SetPoint("TOPLEFT", frame, "TOPLEFT", minX, -minY)
        shape.area:SetSize(math.max(maxX - minX, 1), math.max(maxY - minY, 1))
    end

    local widest = LOOKS.highlight.path.thickness / math.max(map:GetCanvasScale(), 0.01)
    pts = Simplify(Smooth(pts, closed), closed, widest * MIN_SEGMENT_FACTOR)
    local n = #pts / 2
    for i = 1, closed and n or n - 1 do
        local j = (i % n) + 1
        for _, kindName in ipairs({ "lineOutline", "lineCore" }) do
            local line = Acquire(kindName)
            line:SetStartPoint("TOPLEFT", frame, pts[2 * i - 1], -pts[2 * i])
            line:SetEndPoint("TOPLEFT", frame, pts[2 * j - 1], -pts[2 * j])
            line.isCore = kindName == "lineCore"
            shape.lines[#shape.lines + 1] = line
        end
    end
    for _, p in ipairs(CapPoints(pts, closed)) do
        for _, kindName in ipairs({ "capOutline", "capCore" }) do
            local cap = Acquire(kindName)
            cap:SetPoint("CENTER", frame, "TOPLEFT", p[1], -p[2])
            cap.isCore = kindName == "capCore"
            shape.caps[#shape.caps + 1] = cap
        end
    end
    return shape
end

-- Public API ------------------------------------------------------------------------
function Overlay.Draw(map, uiMapID, groups)
    Overlay.Clear()
    lastDraw = { map = map, uiMapID = uiMapID, groups = groups }
    if not frame then
        frame = CreateFrame("Frame", nil, map:GetCanvas())
        frame:SetAllPoints()
    end
    -- Above the map tiles but below POI and rare pins; the default child level sits
    -- underneath the map texture and the lines would be invisible.
    local ok, level = pcall(function()
        return map:GetPinFrameLevelsManager():GetValidFrameLevel("PIN_FRAME_LEVEL_AREA_POI")
    end)
    frame:SetFrameLevel(ok and level and level - 1 or map:GetCanvas():GetFrameLevel() + 100)
    local width, height = frame:GetSize()
    local padding = ZONE_PADDING / math.max(map:GetCanvasScale(), 0.01)
    for _, group in ipairs(groups) do
        local parts = {}
        if ns.db.showSpawnArea and #group.entries >= 2 then
            -- Hull in canvas units so the padding is round, then back to normalized.
            local flat = {}
            for _, entry in ipairs(group.entries) do
                flat[#flat + 1] = entry.x * width
                flat[#flat + 1] = entry.y * height
            end
            local hull = SpawnArea(flat, padding)
            for i = 1, #hull, 2 do
                hull[i], hull[i + 1] = hull[i] / width, hull[i + 1] / height
            end
            parts[#parts + 1] = DrawShape(map, hull, true, "zone")
        end
        for _, entry in ipairs(group.entries) do
            if ns.db.showPaths then
                local points, closed = ns.Coords.ShapeForSpawn(entry.spawn, uiMapID)
                if #points >= 4 then
                    local kind = entry.spawn.path and "path" or "wander"
                    parts[#parts + 1] = DrawShape(map, points, closed, kind)
                end
            end
            -- The primary point has the pin; every other possible spawn point gets a dot.
            if entry ~= group.primary then parts[#parts + 1] = DrawSpot(entry.x, entry.y) end
        end
        if #parts > 0 then
            shapes[group] = parts
            ApplyGroupLook(map, group)
        end
    end
end

-- Zooming: thickness follows immediately; the simplified geometry is rebuilt once the zoom
-- settles, keeping the hovered route highlighted.
function Overlay.UpdateThickness(map)
    for group in pairs(shapes) do ApplyGroupLook(map, group) end
    redrawToken = redrawToken + 1
    local token = redrawToken
    C_Timer.After(REDRAW_DELAY, function()
        if token ~= redrawToken or not lastDraw or lastDraw.map ~= map then return end
        if map:GetMapID() ~= lastDraw.uiMapID then return end
        local keep = highlightedTarget
        Overlay.Draw(map, lastDraw.uiMapID, lastDraw.groups)
        if keep then Overlay.Highlight(map, keep[1], keep[2]) end
    end)
end

-- The drawn group of the rare an escort patrols with, if any.
local function LeaderGroup(group)
    local leader = ns.LeaderOf(ns.Rares[group.npcID])
    if not leader then return nil end
    for g in pairs(shapes) do
        if g.npcID == leader then return g end
    end
end

--- Emphasize the routes and spawn dots of one rare group, or of a list of them (the rares
--- sharing a pin), and dim the rest; nil resets. `colors` ([group] = {r, g, b}) gives
--- groups their own highlight color, so rares sharing a pin can be told apart.
function Overlay.Highlight(map, target, colors)
    highlightedTarget, highlighted = target and { target, colors }, nil
    local list = target and (target.npcID and { target } or target) or {}
    for _, group in ipairs(list) do
        -- An escort has no route of its own: light its leader's.
        local shown = shapes[group] and group or LeaderGroup(group)
        if shown and not (highlighted and highlighted[shown]) then
            highlighted = highlighted or {}
            highlighted[shown] = colors and (colors[shown] or colors[group]) or true
        end
    end
    for g in pairs(shapes) do ApplyGroupLook(map, g) end
end

--- Whether a rare group has anything drawn (route, wander area or spawn dots).
function Overlay.HasShape(group)
    return shapes[group] ~= nil
end
